// The API reference is generated by starlight-openapi, whose labels are in
// English with no way to translate them (HiDeoo/starlight-openapi#132). On a
// French page, a passage in another language must say so (RGAA 8.7): every
// one of these labels in the text of a page is wrapped in <span lang="en">.

/** The starlight-openapi version `ENGLISH_LABELS` was read from. */
export const LABELS_VERSION = '0.27.0';

/** The title starlight-openapi gives its overview pages: routeData.ts replaces it. */
export const OVERVIEW = 'Overview';

/** The other English labels starlight-openapi writes into a page. */
const ENGLISH_LABELS = [
  'Any of',
  'Authentication',
  'Authorizations',
  'Callbacks',
  'Contact',
  'Cookie Parameters',
  'deprecated',
  'Example',
  'Examples',
  'Header Parameters',
  'Headers',
  'Media type',
  'One of',
  'Operations',
  'Parameters',
  'Path Parameters',
  'Query Parameters',
  'Request Body',
  'required',
  'Responses',
  'Terms of Service',
  'Webhooks',
];

/** A label, the longest first so that « Query Parameters » wins over « Parameters ». */
const LABEL = new RegExp(
  `\\b(?:${[...ENGLISH_LABELS].sort((a, b) => b.length - a.length).join('|')})\\b`,
  'g',
);

/**
 * An element whose content cannot hold a <span> or is data (code blocks,
 * scripts, styles, the page title), or the text between two tags.
 */
const TEXT = /(<(pre|script|style|title)\b[\s\S]*?<\/\2>)|>([^<]+)(?=<)/g;

/** A label already marked. */
const MARKED = /<span lang="en">[^<]*<\/span>/g;

/** Wraps every English label of a page's text in <span lang="en">. */
export function markEnglishLabels(html: string): string {
  return html.replace(TEXT, (match: string, ...groups: (string | undefined)[]) => {
    const [skipped, , text = ''] = groups;
    if (skipped) return match;
    return `>${text.replace(LABEL, (label) => `<span lang="en">${label}</span>`)}`;
  });
}

/** The English labels of a page's text that are not wrapped in <span lang="en">. */
export function unmarkedEnglishLabels(html: string): string[] {
  return Array.from(html.replace(MARKED, '').matchAll(TEXT)).flatMap(([, skipped, , text = '']) =>
    skipped ? [] : (text.match(LABEL) ?? []),
  );
}
